class Solution {
public:
    long long minIncrementOperations(vector<int>& nums, int k) {
        long long a = 0, b = 0, c = 0;
        for (int x : nums) {
            long long cost = max(0, k - x);
            long long next_val = min({a, b, c}) + cost;
            a = b;
            b = c;
            c = next_val;
        }
        return min({a, b, c});
    }
};

class Solution {
    public long minIncrementOperations(int[] nums, int k) {
        long a = 0, b = 0, c = 0;
        for (int x : nums) {
            long cost = Math.max(0, k - x);
            long nextVal = Math.min(a, Math.min(b, c)) + cost;
            a = b;
            b = c;
            c = nextVal;
        }
        return Math.min(a, Math.min(b, c));
    }
}

