var minIncrementOperations = function(nums, k) {
    let a = 0n, b = 0n, c = 0n;
    for (const x of nums) {
        const cost = BigInt(Math.max(0, k - x));
        const minPrev = (a < b ? (a < c ? a : c) : (b < c ? b : c));
        const nextVal = minPrev + cost;
        a = b;
        b = c;
        c = nextVal;
    }
    const ans = (a < b ? (a < c ? a : c) : (b < c ? b : c));
    return Number(ans);
};
